function [speed_signals, torque_signals, flux_linkage_signals, angle_and_current_signals] = mfun_fvc_monitored_signals(fbk_in, ref_in, w_M_ref, p)
%MFUN_FVC_MONITORED_SIGNALS Block Monitored signals of the control system.
%   Generated by motulator_export from the MATLAB port of motulator and called by the
%   MATLAB Function block of the library of motulator, whose folder motulator.setup adds
%   to the MATLAB path. The parameters are the fields of the struct p (from the mask, []
%   as NaN).
fbk = observer_outputs_unpack(fbk_in);
ref = references_unpack(ref_in);
% Monitored signals
speed_signals = [w_M_ref; fbk.w_M];
torque_signals = [ref.tau_M; fbk.tau_M];
flux_linkage_signals = [ref.psi_s; abs(fbk.psi_s)];
angle_and_current_signals = [fbk.theta_m; real(fbk.i_s); imag(fbk.i_s)];
end

function s = observer_outputs_unpack(u)
%OBSERVER_OUTPUTS_UNPACK Struct of the signal vector u.
s = struct( ...
    'i_s', complex(u(1), u(2)), ...
    'u_s', complex(u(3), u(4)), ...
    'u_s_zoh', complex(u(5), u(6)), ...
    'psi_s', complex(u(7), u(8)), ...
    'e_o', complex(u(9), u(10)), ...
    'eps', u(11), ...
    'eps_f', u(12), ...
    'psi_a', complex(u(13), u(14)), ...
    'tau_M', u(15), ...
    'w_c', u(16), ...
    'w_m', u(17), ...
    'w_M', u(18), ...
    'theta_c', u(19), ...
    'theta_m', u(20), ...
    'psi_f', u(21), ...
    'h', u(22), ...
    'caught', u(23));
end

function s = references_unpack(u)
%REFERENCES_UNPACK Struct of the signal vector u.
s = struct( ...
    'psi_s', u(1), ...
    'tau_M', u(2), ...
    'u_s', complex(u(3), u(4)));
end
